/**
 * Data generated by a pushbroom imager (SB-01).
 *
 * Each band produces (swath / GSD) pixels per line and (v_g / GSD) lines per second:
 *   R_raw = Σ_bands (swath / GSD_b) · (v_g / GSD_b) · bits_b
 * Compression divides the rate by the compression ratio; a duty cycle (fraction of the
 * orbit spent imaging) turns the rate into a daily volume.
 */

export interface BandSampling {
  gsdM: number
  bits: number
}

/** Uncompressed data rate [bit/s] */
export function rawDataRate(swathKm: number, groundSpeedKmS: number, bands: BandSampling[]): number {
  const swath = swathKm * 1e3
  const v = groundSpeedKmS * 1e3
  return bands.reduce((sum, b) => sum + (swath / b.gsdM) * (v / b.gsdM) * b.bits, 0)
}

/** Data rate after compression [bit/s] */
export function compressedRate(rawBps: number, compressionRatio: number): number {
  return rawBps / compressionRatio
}

/** Volume per day [bit] for a given imaging duty cycle [0–1]; pass body.solarDay for a sol */
export function dailyVolume(rateBps: number, dutyCycle: number, daySeconds = 86400): number {
  return rateBps * daySeconds * dutyCycle
}

/** Time to downlink a volume [s] at a given link rate [bit/s] */
export function downlinkTime(volumeBit: number, linkRateBps: number): number {
  return volumeBit / linkRateBps
}
